`timescale 1ns/1ps

// The grading testbench: rotation over a full lap, a single requester
// kept waiting, the pointer surviving idle cycles, and one-hotness.
module tb;

  localparam int N = 4;

  logic clk = 1'b0;
  always #5 clk = ~clk;

  logic rst_n = 1'b1;
  logic [N-1:0] req = '0;
  logic [N-1:0] grant;
  logic valid;

  rr_arbiter #(.N(N)) dut (
    .clk(clk), .rst_n(rst_n), .req(req), .grant(grant), .valid(valid)
  );

  integer i;

  // Present a request pattern for one cycle and return just after the
  // rising edge, with `grant` still showing that cycle's decision.
  task ask(input [N-1:0] r);
    begin
      @(negedge clk); req = r;
      #1;
    end
  endtask

  // Let the edge happen, so the arbiter's pointer moves on.
  task settle;
    begin
      @(posedge clk); #1;
    end
  endtask

  task reset;
    begin
      @(negedge clk); rst_n = 1'b0; req = '0;
      @(posedge clk); #1;
      rst_n = 1'b1;
    end
  endtask

  function automatic integer onehot_index(input [N-1:0] g);
    integer k, c, idx;
    begin
      c = 0; idx = -1;
      for (k = 0; k < N; k = k + 1) if (g[k]) begin c = c + 1; idx = k; end
      onehot_index = (c == 1) ? idx : -1;
    end
  endfunction

  integer g [0:7];
  integer k, bad_onehot, starved, idx;
  logic   v_none, v_some;
  integer after_idle, lone, skip_absent, resumed;

  initial begin
    $dumpfile("dump.vcd");
    $dumpvars(0, tb);

    // A full lap with everybody asking, twice round.
    reset();
    bad_onehot = 0;
    for (i = 0; i < 8; i = i + 1) begin
      ask(4'b1111);
      idx = onehot_index(grant);
      if (idx < 0) bad_onehot = bad_onehot + 1;
      g[i] = idx;
      settle();
    end

    // Nobody asking: no grant, and the pointer must not move.
    reset();
    ask(4'b1111); settle();        // grants 0
    ask(4'b0000); v_none = valid; settle();
    ask(4'b0000); settle();
    ask(4'b1111); after_idle = onehot_index(grant); settle();

    // One requester, asking for ever: it gets every cycle.
    reset();
    starved = 0;
    for (i = 0; i < 5; i = i + 1) begin
      ask(4'b0100);
      if (onehot_index(grant) != 2) starved = starved + 1;
      settle();
    end
    lone = starved;

    // Absent requesters are skipped rather than wasting a turn.
    reset();
    ask(4'b1001); settle();              // grants 0
    ask(4'b1001); skip_absent = onehot_index(grant); settle();   // grants 3

    // A requester that drops out and comes back.
    reset();
    ask(4'b0011); settle();              // grants 0
    ask(4'b0010); settle();              // grants 1
    ask(4'b0011); resumed = onehot_index(grant); settle();

    // And valid really does follow req.
    ask(4'b0000); v_some = valid;

    $display("CHECK always_one_hot 0 %0d AT %0d", bad_onehot, $time);
    $display("CHECK lap_starts_at_zero 0 %0d AT %0d", g[0], $time);
    $display("CHECK lap_reaches_three 3 %0d AT %0d", g[3], $time);
    $display("CHECK lap_wraps_to_zero 0 %0d AT %0d", g[4], $time);
    $display("CHECK second_lap_matches 1 %0d AT %0d", g[5], $time);
    $display("CHECK idle_makes_no_grant 0 %0d AT %0d", v_none, $time);
    $display("CHECK pointer_survives_idle 1 %0d AT %0d", after_idle, $time);
    $display("CHECK lone_requester_never_waits 0 %0d AT %0d", lone, $time);
    $display("CHECK absent_are_skipped 3 %0d AT %0d", skip_absent, $time);
    $display("CHECK returning_requester_served 0 %0d AT %0d", resumed, $time);
    $display("CHECK valid_low_with_no_req 0 %0d AT %0d", v_some, $time);
    $display("DONE 11");
    $finish;
  end

endmodule

