// A round-robin arbiter.
//
// `grant` is combinational, so a requester sees its grant in the same
// cycle it asks. The only state is `last`, the index granted most
// recently, and it decides where the search starts.

module rr_arbiter #(
    parameter int N = 4            // at least 2
) (
    input  logic         clk,
    input  logic         rst_n,    // synchronous, active low
    input  logic [N-1:0] req,      // one bit per requester
    output logic [N-1:0] grant,    // one-hot, or all zero
    output logic         valid     // high exactly when a grant is made
);

    localparam int IW = (N <= 2) ? 1 : $clog2(N);

    logic [IW-1:0] last;
    logic [IW-1:0] pick;

    // Search the N positions after `last`, cyclically, and take the
    // first requester found.
    always_comb begin
        int i;
        int k;
        grant = '0;
        valid = 1'b0;
        pick  = '0;
        for (i = 1; i <= N; i = i + 1) begin
            k = (int'(last) + i) % N;
            if (!valid && req[k]) begin
                grant[k] = 1'b1;
                valid    = 1'b1;
                pick     = IW'(k);
            end
        end
    end

    always_ff @(posedge clk) begin
        if (!rst_n)     last <= IW'(N - 1);   // so position 0 goes first
        else if (valid) last <= pick;
    end

endmodule
